#!/usr/bin/env bash
set -euo pipefail

# =============================================================================
# FACTS Sea Level Experiment Runner - Apptainer
# Generated by facts-experiment-builder
# =============================================================================

# --- Paths -------------------------------------------------------------------
WORKSPACE="<TMP>/workspace"
DATA_DIR="${WORKSPACE}/data"
EXPERIMENT_NAME="experiments/snapshot"
OUTPUT_DIR="<TMP>/workspace/experiments/snapshot/output-apptainer"
SHARED_IN="<TMP>/workspace/data/shared"
MODULE_IN="<TMP>/workspace/data/module"
SIF_DIR="<TMP>/workspace/apptainer_experiments/sif"

# --- Global params -----------------------------------------------------------
PYEAR_START=2020
PYEAR_END=2150
PYEAR_STEP=10
BASEYEAR=2005
SCENARIO="ssp585"
NSAMPS=50
PIPELINE_ID="abc123"
WORKFLOW1_NAME="wf1"
WORKFLOW2_NAME="wf2"

# --- Helpers -----------------------------------------------------------------

log() { echo "[$(date '+%H:%M:%S')] $*"; }

pull_image() {
    local name="$1"
    local ref="$2"
    local sif="${SIF_DIR}/${name}.sif"
    if [[ ! -f "$sif" ]]; then
        log "Pulling ${ref} -> ${sif}"
        apptainer pull --disable-cache "$sif" "docker://${ref}"
    else
        log "Image already exists: ${sif}"
    fi
}

# Per-service --env flags; set before a service that needs them and reset after.
ENV_ARGS=()

run_service() {
    local name="$1"
    local sif="${SIF_DIR}/${name}.sif"
    shift
    log "Running service: ${name}"
    # --pwd /: the home dir is hidden by --containall/--no-home, so don't start there.
    # ${ENV_ARGS[@]+...}: expands to nothing for an empty array under `set -u`.
    apptainer run \
        --no-home \
        --containall \
        --pwd / \
        "${BINDS[@]}" \
        ${ENV_ARGS[@]+"${ENV_ARGS[@]}"} \
        "$sif" \
        "$@"
    log "Completed: ${name}"
}

wait_for_output() {
    # Poll until an expected output file exists (used to gate stage 2)
    local file="$1"
    local service="$2"
    log "Waiting for output of ${service}: ${file}"
    local attempts=0
    until [[ -f "$file" ]]; do
        sleep 5
        attempts=$((attempts + 1))
        if (( attempts > 360 )); then   # 30-minute timeout
            echo "ERROR: Timed out waiting for ${file}" >&2
            exit 1
        fi
    done
    log "Output ready: ${file}"
}

# --- Setup -------------------------------------------------------------------
mkdir -p \
    "${SIF_DIR}" \
    "<TMP>/workspace/experiments/snapshot/output-apptainer/fair-temperature" \
    "<TMP>/workspace/experiments/snapshot/output-apptainer/ssp-landwaterstorage" \
    "<TMP>/workspace/experiments/snapshot/output-apptainer/tlm-sterodynamics" \
    "<TMP>/workspace/experiments/snapshot/output-apptainer/emulandice-ais" \
    "<TMP>/workspace/experiments/snapshot/output-apptainer/facts-total"

# --- Pull images -------------------------------------------------------------
log "=== Pulling images ==="
pull_image "fair-temperature-0.2.1" "ghcr.io/fact-sealevel/fair-temperature:0.2.1"
pull_image "ssp-landwaterstorage-0.3.0" "ghcr.io/fact-sealevel/ssp-landwaterstorage:0.3.0"
pull_image "tlm-sterodynamics-0.3.2" "ghcr.io/fact-sealevel/tlm-sterodynamics:0.3.2"
pull_image "emulandice-ais-0.2.0" "ghcr.io/fact-sealevel/emulandice:0.2.0"
pull_image "facts-total-wf1-global-0.2.1" "ghcr.io/fact-sealevel/facts-total:0.2.1"
pull_image "facts-total-wf2-global-0.2.1" "ghcr.io/fact-sealevel/facts-total:0.2.1"

# =============================================================================
# Stage 1: Climate module + non-climate-dependent sealevel modules
# =============================================================================
log "=== Stage 1: independent services ==="

# --- fair-temperature ---
BINDS=(
    "--bind=<TMP>/workspace/data/module/fair-temperature:/mnt/module_specific_in"
    "--bind=<TMP>/workspace/data/shared:/mnt/shared_in"
    "--bind=<TMP>/workspace/experiments/snapshot/output-apptainer:/mnt/out"
)
run_service "fair-temperature-0.2.1" \
    "--pipeline-id=abc123" \
    "--nsamps=50" \
    "--scenario=ssp585" \
    "--cyear-start=1850" \
    "--cyear-end=1900" \
    "--smooth-win=19" \
    "--seed=2314" \
    "--rcmip-file=/mnt/module_specific_in/rcmip/rcmip-emissions-annual-means-v5-1-0.csv" \
    "--param-file=/mnt/module_specific_in/parameters/fair_ar6_climate_params_v4.0.nc" \
    "--output-oceantemp-file=/mnt/out/fair-temperature/oceantemp.nc" \
    "--output-climate-file=/mnt/out/fair-temperature/climate.nc" \
    "--output-ohc-file=/mnt/out/fair-temperature/ohc.nc" \
    "--output-gsat-file=/mnt/out/fair-temperature/gsat.nc"

# --- ssp-landwaterstorage ---
BINDS=(
    "--bind=<TMP>/workspace/data/module/ssp-landwaterstorage:/mnt/module_specific_in"
    "--bind=<TMP>/workspace/data/shared:/mnt/shared_in"
    "--bind=<TMP>/workspace/experiments/snapshot/output-apptainer:/mnt/out"
)
run_service "ssp-landwaterstorage-0.3.0" \
    "--pipeline-id=abc123" \
    "--nsamps=50" \
    "--scenario=ssp585" \
    "--baseyear=2005" \
    "--pyear-start=2020" \
    "--pyear-end=2150" \
    "--pyear-step=10" \
    "--location-file=/mnt/shared_in/location.lst" \
    "--fp-file=/mnt/module_specific_in/REL_GROUNDWATER_NOMASK.nc" \
    "--dcyear-start=2020" \
    "--dcyear-end=2040" \
    "--chunksize=50" \
    "--seed=1243" \
    "--pophist-file=/mnt/module_specific_in/UNWPP2012 population historical.csv" \
    "--reservoir-file=/mnt/module_specific_in/Chao2008 groundwater impoundment.csv" \
    "--popscen-file=/mnt/module_specific_in/ssp_iam_baseline_popscenarios2100.csv" \
    "--gwd-file=/mnt/module_specific_in/Konikow2011 GWD.csv" \
    "--gwd-file=/mnt/module_specific_in/Wada2012 GWD.csv" \
    "--output-gslr-file=/mnt/out/ssp-landwaterstorage/gslr.nc"

# =============================================================================
# Stage 2: Sealevel modules depending on climate output
# =============================================================================
log "=== Stage 2: services depending on climate step ==="
wait_for_output "<TMP>/workspace/experiments/snapshot/output-apptainer/fair-temperature/climate.nc" "fair-temperature"
wait_for_output "<TMP>/workspace/experiments/snapshot/output-apptainer/fair-temperature/gsat.nc" "fair-temperature"

# --- tlm-sterodynamics ---
BINDS=(
    "--bind=<TMP>/workspace/data/module/tlm-sterodynamics:/mnt/module_specific_in"
    "--bind=<TMP>/workspace/data/shared:/mnt/shared_in"
    "--bind=<TMP>/workspace/experiments/snapshot/output-apptainer:/mnt/out"
)
run_service "tlm-sterodynamics-0.3.2" \
    "--pipeline-id=abc123" \
    "--nsamps=50" \
    "--scenario=ssp585" \
    "--baseyear=2005" \
    "--pyear-start=2020" \
    "--pyear-end=2150" \
    "--pyear-step=10" \
    "--location-file=/mnt/shared_in/location.lst" \
    "--seed=4321" \
    "--climate-data-file=/mnt/out/fair-temperature/climate.nc" \
    "--model-dir=/mnt/module_specific_in/cmip6/" \
    "--expansion-coefficients-file=/mnt/module_specific_in/scmpy2LM_RCMIP_CMIP6calpm_n18_expcoefs.nc" \
    "--gsat-rmses-file=/mnt/module_specific_in/scmpy2LM_RCMIP_CMIP6calpm_n17_gsat_rmse.nc" \
    "--output-gslr-file=/mnt/out/tlm-sterodynamics/gslr.nc"

# --- emulandice-ais ---
BINDS=(
    "--bind=<TMP>/workspace/data/module/emulandice-ais:/mnt/module_specific_in"
    "--bind=<TMP>/workspace/data/shared:/mnt/shared_in"
    "--bind=<TMP>/workspace/experiments/snapshot/output-apptainer:/mnt/out"
)
run_service "emulandice-ais-0.2.0" \
    "ais" \
    "--pipeline-id=abc123" \
    "--baseyear=2005" \
    "--location-file=/mnt/shared_in/location.lst" \
    "--fprint-wais-file=/mnt/shared_in/FPRINT/fprint_wais.nc" \
    "--fprint-eais-file=/mnt/shared_in/FPRINT/fprint_eais.nc" \
    "--chunksize=50" \
    "--input-data-file=/mnt/out/fair-temperature/gsat.nc" \
    "--output-gslr-file=/mnt/out/emulandice-ais/output-gslr.nc" \
    "--output-gslr-wais-file=/mnt/out/emulandice-ais/output-gslr-wais.nc" \
    "--output-gslr-eais-file=/mnt/out/emulandice-ais/output-gslr-eais.nc" \
    "--output-gslr-pen-file=/mnt/out/emulandice-ais/output-gslr-pen.nc"

# =============================================================================
# Stage 3: Totaling step (parallel, one per workflow × output type)
# =============================================================================
log "=== Stage 3: facts-total ==="

BINDS=(
    "--bind=<TMP>/workspace/data/shared:/mnt/shared_in"
    "--bind=<TMP>/workspace/experiments/snapshot/output-apptainer:/mnt/total_out"
)
run_service "facts-total-wf1-global-0.2.1" \
    "--pyear-start=2020" \
    "--pyear-end=2150" \
    "--pyear-step=10" \
    "--item=/mnt/total_out/ssp-landwaterstorage/gslr.nc" \
    "--output-path=/mnt/total_out/facts-total/wf1_global_total.nc" &
PID_FACTS_TOTAL_WF1_GLOBAL=$!

run_service "facts-total-wf2-global-0.2.1" \
    "--pyear-start=2020" \
    "--pyear-end=2150" \
    "--pyear-step=10" \
    "--item=/mnt/total_out/tlm-sterodynamics/gslr.nc" \
    "--item=/mnt/total_out/emulandice-ais/output-gslr.nc" \
    "--output-path=/mnt/total_out/facts-total/wf2_global_total.nc" &
PID_FACTS_TOTAL_WF2_GLOBAL=$!

wait $PID_FACTS_TOTAL_WF1_GLOBAL || { echo "ERROR: facts-total-wf1-global failed" >&2; exit 1; }
wait $PID_FACTS_TOTAL_WF2_GLOBAL || { echo "ERROR: facts-total-wf2-global failed" >&2; exit 1; }

log "Experiment complete."
